    @Test
    public void testRemoveValueFormatter() {
        ZapposJson zapposJson = ZapposJson.getInstance();
        
        // Define a dummy ValueFormatter for testing purposes
        ValueFormatter<String> dummyFormatter = new ValueFormatter<String>() {
            @Override
            public String format(String value) {
                return "Formatted: " + value;
            }
        };

        // Register the dummy formatter for String class
        zapposJson.addValueFormatter(String.class, dummyFormatter);

        // Verify that the formatter is initially registered
        ValueFormatter<?> retrievedFormatter = zapposJson.getValueFormatter(String.class);
        assertNotNull("Formatter should be registered before removal", retrievedFormatter);

        // Remove the formatter
        zapposJson.removeValueFormatter(String.class);

        // Verify that the formatter is now removed
        retrievedFormatter = zapposJson.getValueFormatter(String.class);
        assertNull("Formatter should be removed", retrievedFormatter);
    }
